import './App.css';
import Gallery from './components/Gallery';
import React, {useState, useEffect} from 'react'
import * as Realm from "realm-web";
const REALM_APP_ID = "keenan-kgkzv"; // e.g. myapp-abcde
const app = new Realm.App({ id: REALM_APP_ID });
const mongodb = app.currentUser.mongoClient("mongodb-atlas");
const plants = mongodb.db("example").collection("plants");





function App() {

  //const [user, setUser] = React.useState(app.currentUser);

  async function pusher (){

    const result = await plants.insertOne({
      name: "lily of the valley",
      sunlight: "full",
      color: "white",
      type: "perennial",
      _partition: "Store 47",
    });
    console.log(result);
  }

  return (
    <div className={"flex flex-wrap content-center justify-center h-screen w-screen"}>
      <p onClick={pusher()} >click meeeeeeeeee</p>
      <div className="block ">
        <div className={"text-center text-4xl m-8 font-mono italic bold"}>Keenan Cassidy</div>
        <Gallery />
      </div>
    </div>
  );
}

export default App;
